process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const GAV='', KAT='';
const DEP=Buffer.from('','base64').toString();
async function jsonSafe(r){ const t=await r.text();
  const a=t.indexOf('['), o=t.indexOf('{');
  const i=(a>=0&&(a<o||o<0))?a:o; if(i<0) return null;
  try{ return JSON.parse(t.slice(i)); }catch(e){ return null; } }
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'v6', content:b64}; if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await jsonSafe(r)||{};
}
async function off(id){ if(!id) return; await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'V6'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await jsonSafe(r);
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  for(const [o,v] of [['ps_uxd_gav',GAV],['ps_uxd_kat',KAT]]){
    const s=await snip('TEMP v6 '+o, "update_option('"+o+"','"+v+"','no');");
    await pause(1800); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  }
  const sd=await snip('TEMP v6 dep', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_v6=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  out.deploy=await jsonSafe(resp);
  await fetch(`${WP}/?ps_v6_val=1&k=dq7m3z`,{headers:{Authorization:AUTH}});

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e).slice(0,200)));
  const dial=[]; page.on('dialog',async d=>{ dial.push(d.message().slice(0,80)); await d.dismiss(); });
  page.setDefaultTimeout(15000);

  /* ===== GAVIMAS ===== */
  try{ await page.goto(`${WP}/?ps_v6_gav=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:45000}); }catch(e){}
  await pause(3000);
  await page.evaluate(()=>{ const i=document.getElementById('g-q');
    i.focus(); i.value='Naujas testas'; i.dispatchEvent(new Event('input',{bubbles:true})); });
  await pause(2500);
  await page.evaluate(()=>{ const b=document.querySelector('#g-rez .nauja'); if(b) b.click(); });
  await pause(2500);
  out.kat_pries=await page.evaluate(()=>document.getElementById('n-kat').options.length);
  out.kat_pvz=await page.evaluate(()=>Array.prototype.slice.call(document.getElementById('n-kat').options,1,6).map(o=>o.textContent));
  /* Filtruojam */
  await page.evaluate(()=>{ const i=document.getElementById('n-kat-q');
    i.value='sausas'; i.dispatchEvent(new Event('input',{bubbles:true})); });
  await pause(800);
  out.kat_po_filtro=await page.evaluate(()=>({
    kiek:document.getElementById('n-kat').options.length,
    sar:Array.prototype.slice.call(document.getElementById('n-kat').options,1).map(o=>o.textContent)}));
  let png=await page.screenshot(); out.s1=await putRaw('screenshots/v6_kategorijos.png', png.toString('base64'),'v6');

  /* Sargas: bandom eiti i Kataloga uzpildzius */
  await page.evaluate(()=>{ document.getElementById('n-pav').value='TESTAS sargas'; });
  await page.evaluate(()=>{ const a=document.querySelector('.psgav-bar a[href*="ps-katalogas"]'); if(a) a.click(); });
  await pause(1200);
  out.sargas_gavime=dial.length?dial[dial.length-1]:'neklause';
  out.liko_gavime=page.url().indexOf('ps-gavimas')>=0;

  /* ===== KATALOGAS ===== */
  try{ await page.goto(`${WP}/?ps_v6_kat=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:45000}); }catch(e){}
  await pause(3000);
  /* Atidarom 8-a preke */
  await page.evaluate(()=>{ const a=document.querySelectorAll('.pskat-t tbody tr[data-id] a.atv')[7]; if(a) a.click(); });
  await pause(4000);
  out.kortele=await page.evaluate(()=>{
    const h=document.querySelector('.kort-pav-t'); return h?h.textContent.trim().slice(0,40):null; });
  /* Keiciam kaina ir irasom — ar zalias patvirtinimas */
  out.kort_yra=await page.evaluate(()=>!!document.querySelector('.kort-kaina input'));
  if(!out.kort_yra){
    out.kort_html=await page.evaluate(()=>{ const t=document.querySelector('.kort-turinys'); return t?t.innerText.slice(0,200):'nera'; });
    await putRaw('analize/v6.json', Buffer.from(JSON.stringify(out,null,2)).toString('base64'),'v6');
    await br.close(); await off(sd.id); return;
  }
  const k0=await page.evaluate(()=>document.querySelector('.kort-kaina input').value);
  await page.evaluate(()=>{ const i=document.querySelector('.kort-kaina input');
    i.focus(); i.value=(parseFloat(i.value||'1')+0.01).toFixed(2); i.dispatchEvent(new Event('input',{bubbles:true})); });
  await pause(400);
  await page.evaluate(()=>{ document.querySelector('.kort-kaina input')
    .dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true})); });
  await pause(2500);
  out.irasyta_zyme=await page.evaluate(()=>document.querySelector('.kort-kaina input').classList.contains('irasyta'));
  png=await page.screenshot(); out.s2=await putRaw('screenshots/v6_irasyta.png', png.toString('base64'),'v6');
  /* Atstatom */
  await page.evaluate((v)=>{ const i=document.querySelector('.kort-kaina input');
    i.focus(); i.value=v; i.dispatchEvent(new Event('input',{bubbles:true}));
    i.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true})); }, k0);
  await pause(2500);
  /* Uzdarom — ar grazina i ta pacia vieta */
  await page.evaluate(()=>{ const x=document.querySelector('.kort-x'); if(x) x.click(); });
  await pause(1500);
  out.po_uzdarymo=await page.evaluate(()=>{
    const t=document.querySelector('.pskat-t tbody tr.buvo');
    if(!t) return 'zymes nera';
    const r=t.getBoundingClientRect();
    return {pav:t.innerText.slice(0,40).replace(/\n/g,' '), matoma:r.top>0&&r.top<window.innerHeight};
  });
  png=await page.screenshot(); out.s3=await putRaw('screenshots/v6_grizta.png', png.toString('base64'),'v6');

  out.js_klaidos=jsErr.slice(0,6);
  out.dialogai=dial;
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await jsonSafe(r);
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putRaw('analize/v6.json', Buffer.from(JSON.stringify(out,null,2)).toString('base64'),'v6');
}
main().catch(async e=>{ await putRaw('analize/v6.json', Buffer.from(JSON.stringify({klaida:String(e).slice(0,300)})).toString('base64'),'v6'); });
